import { highlightCode } from "@/lib/shiki";
import { CopyButton } from "./copy-button";
import type { BundledLanguage } from "shiki";

interface CodeBlockProps {
  code: string;
  lang?: string;
  className?: string;
  filename?: string;
  lineNumbers?: boolean;
}

/**
 * Server Component CodeBlock with cached Shiki highlighting.
 * 
 * PERFORMANCE: Uses a singleton highlighter pattern to avoid the
 * expensive (~200-500ms) cost of creating a new highlighter per render.
 */
export async function CodeBlock({
  code,
  lang = "tsx",
  className,
  filename,
  lineNumbers = true
}: CodeBlockProps) {
  // Use our cached highlighter for instant highlighting
  const html = await highlightCode(code.trim(), lang as BundledLanguage);

  return (
    <div
      data-code-block
      data-line-numbers={lineNumbers ? "true" : "false"}
      className={`relative text-sm w-full border border-border overflow-hidden bg-zinc-100 dark:bg-zinc-900/50 ${className?.includes('h-full') ? 'flex flex-col ' : ''}${className || "rounded-xl"}`}
    >
      {/* Optional filename header */}
      {filename && (
        <div className="flex items-center gap-2 px-4 py-2.5 border-b border-border bg-zinc-200/50 dark:bg-zinc-900/80">
          <svg className="h-4 w-4 text-muted-foreground" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z" />
            <polyline points="14 2 14 8 20 8" />
          </svg>
          <span className="text-xs font-mono text-muted-foreground">{filename}</span>
        </div>
      )}

      <div className={`relative group ${className?.includes('h-full') ? 'flex-1 min-h-0 flex flex-col' : 'h-full'}`}>
        <CopyButton code={code.trim()} />
        <div
          className={`[&_pre]:p-4 [&_pre]:overflow-x-auto overflow-auto ${className?.includes('max-h-none') ? (className?.includes('h-full') ? 'flex-1 min-h-0' : 'h-full') : 'max-h-[500px]'}`}
          dangerouslySetInnerHTML={{ __html: html }}
        />
      </div>
    </div>
  );
}

"use client"

import * as React from "react"
import { Code2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { DocsCodePanel } from "@/components/docs-code-panel"
import { useDocStore } from "@/hooks/use-doc-store"
import { useSmoothCodeHeight } from "@/hooks/use-smooth-code-height"

interface DynamicCodeBlockProps {
  originalCode: string
  defaultHtml: string
  className?: string
  variantCodes?: string[]
  variantTitles?: string[]
  hideDefaultTab?: boolean
}

async function fetchHighlightedTsx(code: string): Promise<string> {
  const response = await fetch("/api/docs/source", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ code, lang: "tsx" }),
  })

  if (!response.ok) {
    throw new Error("Failed to highlight code")
  }

  const data = (await response.json()) as { html?: string }
  return data.html ?? ""
}

export function DynamicCodeBlock({
  originalCode,
  defaultHtml,
  className,
  variantCodes = [],
  variantTitles = [],
  hideDefaultTab = false,
}: DynamicCodeBlockProps) {
  const { activeVariantIndex, setActiveVariantIndex } = useDocStore()
  const [variantHtmlMap, setVariantHtmlMap] = React.useState<Record<number, string>>({})
  const [visibleHtml, setVisibleHtml] = React.useState(defaultHtml)
  const [isSwitching, setIsSwitching] = React.useState(false)

  const tabs = React.useMemo(() => {
    const items: { id: string; label: string }[] = []
    if (!hideDefaultTab) {
      items.push({ id: "default", label: "Default" })
    }
    variantTitles.forEach((title, i) => {
      items.push({ id: String(i), label: title })
    })
    return items
  }, [hideDefaultTab, variantTitles])

  const activeTab = React.useMemo(() => {
    if (activeVariantIndex === -1) return hideDefaultTab ? tabs[0]?.id ?? "default" : "default"
    return String(activeVariantIndex)
  }, [activeVariantIndex, hideDefaultTab, tabs])

  const targetHtml =
    activeVariantIndex === -1 ? defaultHtml : variantHtmlMap[activeVariantIndex]

  const rawCodeToUse =
    activeVariantIndex === -1
      ? originalCode
      : variantCodes[activeVariantIndex] || originalCode

  const { contentRef, contentHeight, wrapperProps } = useSmoothCodeHeight([
    visibleHtml,
    activeVariantIndex,
  ])
  const hasUnboundedHeight = className?.includes("max-h-none")
  const resolvedWrapperStyle = hasUnboundedHeight
    ? wrapperProps.style
    : {
        ...wrapperProps.style,
        height:
          contentHeight !== undefined
            ? Math.min(contentHeight, 500)
            : wrapperProps.style.height,
      }

  React.useEffect(() => {
    if (hideDefaultTab && activeVariantIndex === -1 && variantTitles.length > 0) {
      setActiveVariantIndex(0)
    }
  }, [hideDefaultTab, activeVariantIndex, variantTitles.length, setActiveVariantIndex])

  React.useEffect(() => {
    let cancelled = false

    const prefetchVariants = async () => {
      const entries = await Promise.all(
        variantCodes.map(async (code, index) => {
          if (!code) return null
          try {
            const html = await fetchHighlightedTsx(code)
            return { index, html }
          } catch {
            return null
          }
        })
      )

      if (cancelled) return

      setVariantHtmlMap((prev) => {
        const next = { ...prev }
        for (const entry of entries) {
          if (entry?.html) {
            next[entry.index] = entry.html
          }
        }
        return next
      })
    }

    prefetchVariants()
    return () => {
      cancelled = true
    }
  }, [variantCodes])

  React.useEffect(() => {
    if (targetHtml) {
      setIsSwitching(true)
      setVisibleHtml(targetHtml)
      const timer = window.setTimeout(() => setIsSwitching(false), 200)
      return () => window.clearTimeout(timer)
    }
    return undefined
  }, [targetHtml])

  const handleTabChange = (id: string) => {
    if (id === "default") {
      setActiveVariantIndex(-1)
      return
    }
    setActiveVariantIndex(Number(id))
  }

  const isLoadingActiveVariant =
    activeVariantIndex >= 0 && !variantHtmlMap[activeVariantIndex]

  return (
    <DocsCodePanel
      icon={Code2}
      copyCode={rawCodeToUse.trim()}
      tabs={tabs.length > 1 ? tabs : undefined}
      activeTab={activeTab}
      onTabChange={handleTabChange}
      tabListAriaLabel="Example variant"
      className={className}
    >
      <div
        {...wrapperProps}
        style={resolvedWrapperStyle}
        className={cn(wrapperProps.className, className?.includes("h-full") && "h-full")}
      >
        <div
          ref={contentRef}
          className={cn(
            "transition-opacity duration-150",
            (isSwitching || isLoadingActiveVariant) && "opacity-70",
            hasUnboundedHeight
              ? "h-full"

interface ImportCodeBlockProps {
  html: string
}

export function ImportCodeBlock({ html }: ImportCodeBlockProps) {
